SELECT
(i.id) as 'inspection_id',
UNIX_TIMESTAMP(i.createdAt) as 'inspection_date',
UNIX_TIMESTAMP(i.updatedAt) as 'inspection_last_modified',
COALESCE(i.report ->> '$.bookingCode', 'None') as 'inspection_booking_code',
COALESCE(i.report ->> '$.forename', 'None') as 'inspection_forename',
COALESCE(i.report ->> '$.surname', 'None') as 'inspection_surname',
COALESCE(i.report ->> '$.email', 'None') as 'inspection_email',
COALESCE(i.report ->> '$.phone', 'None') as 'inspection_phone',
(i.qcScore) as 'inspection_qc_score',
COALESCE(substring_index(i.report ->> '$.leadsource', '.', -1), 'None') as 'inspection_leadsource',
CASE WHEN i.endTime IS NULL THEN IF(ROUND((UNIX_TIMESTAMP(i.createdAt)*1000 - i.startTime)/60000,0) > 120, NULL, ROUND((UNIX_TIMESTAMP(i.createdAt)*1000 - i.startTime)/60000,0))
ELSE ROUND((i.endTime - i.startTime)/60000, 0) 
END as 'inspection_duration',
(i.inspector) as 'inspector',
UNIX_TIMESTAMP(i.deletedAt) as 'deleted_at',
(i.country) as 'country_id',
(i.carId) as 'car_id',
(i.originalInspection) as 'original_inspection_id',
IF(i.type = 'qualityCheck', 'Quality Check', COALESCE(i.report ->> '$.inspectionType', 'Regular')) as 'inspection_type',
i.report ->> '$.make' as 'car_manufacturer',
i.report ->> '$.model' as 'car_model',
i.report ->> '$.trim' as 'trim',
substring_index(i.report ->> '$.transmission', '.', -1) as 'transmission',
i.report ->> '$.year' as 'year',
COALESCE(JSON_LENGTH(i.comments), 0) as 'inspection_number_of_comments',
COALESCE(JSON_LENGTH(i.damages), 0) as 'inspection_number_of_damages',
i.report ->> '$.address' as 'address',
i.report ->> '$.chassisNumber' as 'chassis_number',
substring_index(i.report ->> '$.chassisColor', '.', -1) as 'chassis_color',
substring_index(i.report ->> '$.invoices', '.', -1) as 'invoice_type',
substring_index(i.report ->> '$.invoiceVAT', '.', -1) as 'invoice_vat',
i.report ->> '$.deptTax' as 'debt_tax',
i.report ->> '$.deptOther' as 'debt_other',
i.report ->> '$.registrationNumber' as 'registration_number',
substring_index(i.report ->> '$.location', '.',-1) as 'location',
substring_index(i.report ->> '$.pickupLocation', '.',-1) as 'pickup_location',
substring_index(i.report ->> '$.invoiceIssuedBy', '.',-1) as 'invoice_issued_by',
substring_index(i.report ->> '$.invoiceOrigin', '.',-1) as 'invoice_origin',
i.report ->> '$.invoiceCount' as 'number_of_invoices',
i.report ->> '$.numberOfOwners' as 'number_of_owners',
i.report ->> '$.environmentInspectionExpire' as 'environment_inspection_expire',
i.report ->> '$.environmentClass' as 'environmental_class',
if(i.purchased=1, true, false) as 'is_purchased',
if(i.inAuction = 0, false, true) as 'is_auctioned',
i.report ->> '$.location_placeId' as 'inspection_place_id',
i.report ->> '$.auctionCity' as 'auction_city',
(i.report) as 'inspection_report',
(i.lastEditor) as 'last_editor',
(i.categories) as 'qc_category_scores',
i.nonMatchingFields ->> '$' as 'non_matching_fields',
from_unixtime((i.startTime)/1000,'%Y-%m-%d %H:%i:%s') as 'start_time',
from_unixtime((i.endTime)/1000,'%Y-%m-%d %H:%i:%s') as 'end_time',
i.configId as 'config_id',
CAST(i.report ->> '$.mileage' AS UNSIGNED) as 'mileage',
COALESCE(JSON_LENGTH(i.galleries), 0) as 'inspection_number_of_images',
(i.colorBodyPartMap) as 'color_body_part_map',
i.galleries as 'galleries',
i.group as inspection_group
FROM fcgInspection.inspection i
where i.updatedAt >= '{{params.start_ts}}' and i.updatedAt < '{{params.end_ts}}'